            final long modulo = 1000000007L;
            TransitionMatrix result = new TransitionMatrix();
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    long x = 0L;
                    for (int k = 0; k < 4; k++) {
