                    }
                    result.set(i, j, x);
                }
            }
            return result;
        }
    }

    public static TransitionMatrix identityMatrix() {
        TransitionMatrix result = new TransitionMatrix();
        result.set(0, 0, 1L);
        result.set(1, 1, 1L);
        result.set(2, 2, 1L);
        result.set(3, 3, 1L);
        return result;
    }

    public static TransitionMatrix antMatrix() {
        TransitionMatrix result = new TransitionMatrix();
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                result.set(i, j, 1L);
            }
